 public void run()throws Exception{String[]a=getScriptArgs();if(a.length!=2)throw new IllegalArgumentException("input output");List<String>ls=Files.readAllLines(Paths.get(a[0]),StandardCharsets.UTF_8);FunctionManager fm=currentProgram.getFunctionManager();Memory mem=currentProgram.getMemory();try(PrintWriter w=new PrintWriter(new OutputStreamWriter(new FileOutputStream(a[1]),StandardCharsets.UTF_8))){w.println("entry\tname\tsource\tdomain\tevidence\tbody_bytes\tbody_sha256");int n=0;for(int i=1;i<ls.size();i++){String[]p=ls.get(i).split("\t",-1);if(p.length<3)throw new RuntimeException("cols "+i);long e=Long.parseUnsignedLong(p[0],16);Function f=fm.getFunctionAt(currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(e));if(f==null||f.isExternal())throw new RuntimeException("missing "+p[0]);if(pref(f,"GFZ.V120.PrimaryOwner.")||tag(f,"GFZ.V120.FinalNoPrimaryOwner")||pref(f,"GFZ.V121.CodeDomain."))throw new RuntimeException("already classified "+p[0]);String ev=p.length>=4?p[3]:"Current-function direct string identity supports native domain classification.";w.printf("%08X\t%s\t%s\t%s\t%s\t%d\t%s%n",e,f.getName(),f.getSymbol().getSource().toString(),p[1],ev.replace("\t"," ").replace("\n"," ").replace("\r"," "),f.getBody().getNumAddresses(),bh(f,mem));n++;}println("ENRICH_CURRENT_BODY_MANIFEST_PASS rows="+n);}}
